class Order {
  constructor(public type: string, public amount: number) {}

  calculatePrice() {
    if (this.type === 'standard') return this.amount * 1.0;
    if (this.type === 'discount') return this.amount * 0.8;
    if (this.type === 'premium') return this.amount * 1.2;
    return this.amount;
  }
}

class Notification {
  constructor(public type: string, public payload: any) {}
}

class Notifier {
  send(n: Notification) {
    switch (n.type) {
      case 'email': return this.sendEmail(n.payload);
      case 'sms': return this.sendSms(n.payload);
      default: return this.sendPush(n.payload);
    }
  }
}

// Version A
abstract class Pricing {
  abstract price(order: Order): number
}
class StandardPricing extends Pricing { price(o: Order){ return o.qty * 10 } }
class DiscountPricing extends Pricing { price(o: Order){ return o.qty * 8 } }

// Version B
function priceOrder(order: Order) {
  switch(order.type) {
    case 'standard': return order.qty * 10
    case 'discount': return order.qty * 8
  }
}
